-- Supplement Informatique NS3-NS4 (matiere_id=17)
-- Objectif : porter chaque chapitre à ≥ 20 questions

DO $$
DECLARE chap_id INTEGER;
BEGIN
  SELECT id INTO chap_id FROM chapitres WHERE matiere_id = 17 AND titre = 'Algorithmique avancée : complexité et paradigmes' AND niveau_v4 = 'NS3';
  IF chap_id IS NOT NULL THEN
  END IF;
END $$;

